arguments.command:
curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{"query":"{ __schema { queryType { fields { name args { name type { name } } } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for f in d['data']['__schema']['queryType']['fields']:
    if 'project' in f['name'].lower() or 'issue' in f['name'].lower():
        print(f['name'], [(a['name'], a['type']['name']) for a in f['args']])"

